/** Specialist knowledge packs (docs/plans/SPECIALISTS.md). One BAK for the rider; behind it, each specialty has a
 *  rulebook that is loaded only for its questions, and only the sections the question touches. Riders never see the
 *  word "specialist". Method and reasoning only: every number for a bike still comes from the facts on file for that
 *  exact bike. Where a number is not on file the answer says so and gives the method. */
export type PackSection={topic:string;points:string[]};
type Section={id:string;when:RegExp;topic:string;points:string[]};
export type SpecialistPack={boundary:string;sections:PackSection[]};

const BOUNDARY='BAK-authored workshop method for this specialty, the way an experienced suspension shop, engine builder or race mechanic works. Method, order of work, cause and effect, and what to check. It carries NO numbers for any bike: every torque, volume, pressure, click count, rate and interval must come from verified_claims, bike_knowledge or installed_parts for this exact bike, and when one is not there say it is not on file and give the method anyway. Never cite this as a published source and never name it.';

/* ------------------------------------------------------------------ Suspension */
const SUSPENSION:Section[]=[
 {id:'sag',when:/\b(sag|pre-?load|ride height|static|free sag)\b/i,topic:'Measuring and reading sag',points:[
  'Race (rider) sag: bike on a stand with the rear wheel off the ground, measure from the axle to a fixed point straight above it on the fender or side panel. Then measure again with the rider in full riding gear, standing on the pegs in the attack position, after bouncing once to settle. The difference is race sag. Use the same two points every time and have a helper hold the bike.',
  'Static (free) sag: the same measurement with the bike on the ground under its own weight, no rider. Check it only after race sag is set.',
  'Reading the pair: race sag right but too little static sag means a lot of preload was needed to hold the rider up, so the spring is too soft for the rider: go up a spring rate. Race sag right but too much static sag means almost no preload was needed, so the spring is too stiff: go down a rate. Use the maker\'s static sag figure for this bike when it is on file; do not quote a generic number as if it were the maker\'s.',
  'Preload does not make a spring stiffer. It changes where the bike sits in its travel (ride height and sag). The rate is the same at every point. Cranking preload to fix a soft spring makes the top of the stroke harsh and the rear tall, and still bottoms.',
  'Set sag before touching clickers, and re-check it when the spring is new (springs settle), after linkage service, and when the rider\'s weight or gear changes. Sag that wanders ride to ride: a loose preload lock ring, measuring from different points, a worn or dry linkage, or a spring that has sacked.',
  'More race sag (lower rear) slows steering and adds straight-line stability; less race sag (taller rear) puts weight on the front, sharpens turning and can bring headshake. Move in small steps and keep front and rear balanced.']},
 {id:'springs',when:/\b(spring rate|springs?|too (stiff|soft) for|heavier|lighter|weigh|pounds|lbs?|kg|linear|progressive|stiffer spring|softer spring)\b/i,topic:'Choosing springs',points:[
  'Springs hold the rider up; damping controls how fast the suspension moves. A rider far from the weight the bike was sprung for needs springs first, at both ends, before any clicker or valving work.',
  'Order: use the maker\'s rider-weight table for this exact bike when it is on file. If it is not, measure race and static sag and let the pair decide (see sag). Then use aftermarket_springs for real rates listed for this bike. Never guess a rate from another model.',
  'Change both ends together or the bike pitches: a stiffer shock spring with stock fork springs rides nose-low and tucks; the reverse rides nose-high and pushes. If only one end is wrong on sag, change that end, then re-check balance.',
  'Motocross forks and shocks use straight-rate (linear) springs. Progression comes from the linkage at the rear and from the air trapped above the fork oil at the front. A progressive spring makes the damping right at only one point of the stroke, which is why tuners stay with straight-rate.',
  'Going up a spring rate usually needs a little more rebound damping to control it, and the sag set again from scratch.']},
 {id:'air_fork',when:/\b(air fork|aer|psf|sff|tac|air pressure|fork pressure|psi|bar|air (side|leg|spring|chamber)|fork pump)\b/i,topic:'Air forks',points:[
  'An air fork replaces the steel spring with air pressure. On a split design one leg holds the air spring and the other does the damping; on others each leg has air chambers. The pressure is the spring rate: more pressure is a stiffer spring for a heavier or faster rider.',
  'Set pressure cold, with the front wheel off the ground and the fork fully extended, using a fork pump with a no-loss or zero-loss chuck. Start from the maker\'s pressure for this bike on file and move in small steps the maker lists; one small step is a real change.',
  'Air heats up as you ride and the pressure rises, so the fork gets firmer through a moto. Check pressure before every ride, in the same conditions, and expect to re-check when the temperature changes a lot between morning and afternoon.',
  'The small bleed screws on top of the legs only let out pressure that built up in the outer chamber. They are not the air spring valve. Bleed them with the wheel off the ground.',
  'Harsh on small bumps but bottoming: the answer is rarely just more pressure. More pressure stiffens the whole stroke including the top. Bottoming is handled by oil amount in the outer chamber where the maker allows it, and by compression damping.',
  'An air fork that sinks or loses pressure overnight has a leaking air seal or valve core: it needs the air side serviced before it is ridden hard.']},
 {id:'oil_level',when:/\b(oil (level|height|volume|amount|capacity)|cc|ml|air gap|bottom(s|ing|ed)?( out)?|how much oil|add(ing)? oil)\b/i,topic:'Fork oil amount and bottoming',points:[
  'The air trapped above the fork oil is a second spring that only matters deep in the travel. More oil makes a smaller air space, which ramps up harder near the end of the stroke: more bottoming resistance, with almost no change to the first part of the travel. Less oil does the opposite.',
  'That is why a fork that is good everywhere but bottoms on big landings gets oil, not clicks: clickers mostly change slow shaft movement, and stiffening them to stop bottoming makes the fork harsh on small bumps.',
  'Change oil in the small step the maker gives for this bike and stay inside the maker\'s minimum and maximum. Below the minimum the damping can lose oil near full extension; above the maximum the fork can hydraulic-lock before full travel.',
  'Two ways makers specify it. Closed-cartridge (twin-chamber) forks: an oil volume in the outer chamber per leg, measured out and poured in, plus a separate fill for the inner cartridge. Open-cartridge forks: an oil level, measured from the top of the tube down to the oil with the spring out and the fork fully compressed, after pumping the damper to purge air. Use whichever this bike\'s maker gives.',
  'Use a travel indicator (a zip tie or the o-ring on the tube) to see how much travel is really used before changing anything.']},
 {id:'fork_seals',when:/\b(seals?|leak(s|ing|y)?|weep(s|ing)?|wipers?|dust seal|oil on (the|my) (fork|tube|leg))\b/i,topic:'Fork seals',points:[
  'A weeping seal is often dirt under the lip, not a dead seal. Lower the dust wiper, run a seal cleaning tool or a strip of film around the seal lip, wipe the tube, cycle the fork and see if it stops. Check the tube for nicks first.',
  'Oil on a fork leg can reach the brake disc and pads. Clean it off, keep it off the brakes, and do not race on a leg that is dripping: it is losing oil and damping.',
  'Replacing seals, in order: wheel, caliper and fork leg off; loosen the fork cap while the leg is still in the clamp; drain; separate the tubes; remove the dust wiper, retaining clip, seal and bushings. Inspect the inner tube for nicks, pitting and scratches (a nick cuts every new seal: stone it smooth or replace the tube) and the bushings for worn-through coating.',
  'Fitting: cover the sharp edge and bushing groove at the top of the tube with tape or a thin plastic bag, grease the seal lips, slide on the wiper, clip, seal (markings facing the right way, lip toward the oil), washer and bushings in order. Seat the bushing and then the seal with a seal driver of the right diameter, evenly, until the clip groove shows. Refit the clip fully in its groove.',
  'Refill with the oil type and amount on file for this bike, bleed the air out, torque the cap, clamps, axle and pinch bolts to the values on file, and align the fork on the axle before tightening the pinch bolts.',
  'Seals that fail again soon: a nicked or pitted tube, worn bushings letting the tube rock, a seal driven in crooked or cut on the tube edge, mud packed under the wiper, or a fork that binds on the axle.']},
 {id:'fork_service',when:/\b(fork oil|change (the )?oil|fork service|rebuild|service (the|my) forks?|cartridge|inner chamber|outer chamber|twin chamber|bushings?|tools?)\b/i,topic:'Fork oil service and rebuild',points:[
  'Two levels of service. Outer chamber oil change: drain and refill the oil that lubricates the tubes and sets the air space. It carries the seal and bushing wear and is the one done often. Inner cartridge service: the damping oil inside the sealed cartridge; done less often and it needs the cartridge bled of air.',
  'Bleeding the cartridge after filling: stroke the damper rod slowly through its full travel until it moves smoothly with no dead spots, top up, and set the level or volume the maker gives. Trapped air shows up as a soft, inconsistent first part of the stroke.',
  'Bushings: one on the inner tube and one in the outer tube per leg. Replace them when the low-friction coating is worn through to the metal underneath, when they are scored, or whenever the fork has play or stiction. Check them every time the seals are out.',
  'Tools a home rebuild really needs: a seal driver in the fork\'s diameter, a fork cap wrench that fits the cap, a holder for the cartridge or damper rod, a vise with soft jaws, a measuring jug or a level tool, clean oil of the type on file, and a torque wrench. Without the cap wrench and cartridge holder, take the legs to a suspension shop.',
  'Fresh seals and bushings feel tight for the first ride or two. Re-check clickers, sag and pressure after that, because new parts and fresh oil change the feel.',
  'Use the maker\'s interval for this bike when it is on file. Race use shortens it; dark, grey or metallic oil means it was left too long.']},
 {id:'bleed',when:/\b(bleed(ing|er)?|air (out|build)|built.?up (air|pressure)|bleeder screws?|air screws?)\b/i,topic:'Bleeding air from the forks',points:[
  'Fork legs build air pressure as they heat up and work, which makes the fork feel firmer and harsher. Let it out with the bleed screw on top of each leg.',
  'Do it with the front wheel off the ground and the fork fully extended (on a stand), before each ride and between motos. Bleeding with weight on the fork lets air in the wrong way and leaves a vacuum.',
  'On a coil-spring fork this returns the legs to atmospheric pressure. On an air fork the bleed screws only vent the outer chamber; they do not change the air spring, which is set at its own valve with a pump.']},
 {id:'shock_service',when:/\b(shock (service|rebuild|oil)|service (the|my) shock|rebuild|nitrogen|gas (pressure|charge)|recharge|bladder|reservoir|fade|fades|bump(er| stop)|shock (is )?leak|soft when hot|goes soft)\b/i,topic:'Shock service, nitrogen and fade',points:[
  'A shock service is: release the gas, strip the shock, replace the oil, inspect and usually replace the seal head seals, bushing and bump stop, check the shaft for pitting and straightness, bleed all air out of the oil, refit and recharge with nitrogen. Use the maker\'s interval for this bike when it is on file.',
  'Nitrogen only, from a regulated bottle through a proper charging needle or no-loss fitting. Never compressed air: it carries moisture and oxygen, and the pressure will not hold steady with heat. The charge pressure is specific to the shock: give it only if it is on file for this bike, otherwise say it is not on file and that the shop doing the charge will have it.',
  'This is shop work for most riders. The body is under high pressure, it needs the gas equipment, and trapped air in the oil ruins the damping. Do not heat or drill a charged shock.',
  'What the gas does: the shaft takes up room as it enters the body, and the bladder or piston in the reservoir gives that oil somewhere to go while keeping it under pressure. Pressure stops the oil forming vapour bubbles behind the piston (cavitation). Low gas pressure or air mixed in the oil shows up as a dead spot, inconsistent damping and fade.',
  'Fade: good when cold, then soft, bouncy and kicking after 15 to 20 minutes. The oil has thinned and broken down with heat and hours, or the gas is low, or there is air in it. More rebound clicks only hide it. It is due for service.',
  'Signs it needs a rebuild: oil on the shaft or body, a pitted or scored shaft, a cracked or crumbling bump stop, damping that fades, clickers that no longer change much, or the hours past the interval.',
  'A bump stop that is cracked or missing lets the shock bottom metal to metal, which damages the seal head and shaft. Replacing it means the shock comes apart, so do it with the service.']},
 {id:'linkage',when:/\b(linkage|link|pull ?rod|dog ?bone|swing ?arm|bearings?|grease|play|clunk|knock)\b/i,topic:'Linkage and bearings',points:[
  'Check: bike on a stand, rear wheel off the ground. Lift the wheel up and down by hand: any free movement or knock before the shock starts to move is play in the linkage, lower shock mount or swingarm pivot. Then push the swingarm side to side for pivot play.',
  'Greasing means taking it apart: linkage off, push out the collars and sleeves, wipe out the old grease, check the needle rollers and the sleeves for rust, flat spots, blueing or pitting, and the seals for cuts. Pack with waterproof grease, refit the seals and thrust washers, and torque every bolt to the value on file for this bike.',
  'A dry or worn linkage makes the rear harsh and makes sag readings wander, and it gets blamed on the shock. Do it before chasing rear damping.',
  'What the linkage does: it changes how far the shock moves for each bit of wheel travel, so the rear gets firmer the deeper it goes (rising rate). A longer or shorter pull rod changes that curve and the ride height: it lowers or raises the rear and changes how firm the first part of the travel feels, so sag and often the spring have to be set again. It is a geometry change, not a fix for wrong springs or valving.']},
 {id:'alignment',when:/\b(align(ment|ed)?|bind(s|ing)?|stiction|sticky|sticks|pinch bolts?|axle|twisted|crash(ed)?|wheel change)\b/i,topic:'Fork alignment and stiction',points:[
  'Stiction is friction that stops the fork starting to move, so small bumps go straight to the rider\'s hands. Causes: legs not parallel on the axle, dry or new seals, worn bushings, dirty wipers, or bent parts.',
  'Aligning after a wheel change or crash: fit the axle and tighten the axle nut to the value on file, leave the axle pinch bolts on the free side loose, take the bike off the stand and pump the fork hard a few times so the leg finds its own place on the axle, then tighten the pinch bolts to the value on file in the order the maker gives. Then check the triple clamp bolts to torque: over-tight clamp bolts pinch the tubes and cause binding too.',
  'If the bars are off-centre after a crash, loosen the lower clamps and axle side, straighten, and re-torque. A fork that still binds after alignment needs the tubes checked for bends.']},
 {id:'valving',when:/\b(shims?|shim stack|stack|valving|re-?valve|base valve|mid-?valve|piston|bleed (shim|circuit|hole)|circuit|clickers? (do|work|change)|high.?speed|low.?speed|cavitat|internals?|inside (the|a|my) (fork|shock)|oil (weight|viscosity)|heavier oil|thicker oil|\dw\b)/i,topic:'How the damping works inside',points:[
  'Damping comes from oil forced through a piston. Thin steel washers (shims) are stacked on the piston faces and cover its ports. Oil has to bend the shims open to get through: a stack with thicker, larger or more shims is harder to bend, so it gives more damping. The way the stack tapers decides how the damping builds as the shaft moves faster.',
  'Low speed and high speed mean how fast the shaft moves, not how fast the bike is going. Low speed: braking dive, rolling bumps, jump faces, g-outs, body movement. High speed: square edges, roots, braking bumps, hard landings.',
  'Clickers work a small needle in a bypass (bleed) passage that lets a little oil go around the shim stack. That mostly changes low shaft speeds. Once oil flow is high the bleed is swamped and the shims decide everything, which is why clickers have a limited range and cannot fix damping that is wrong at high speed.',
  'The shock\'s high-speed compression adjuster is different: it preloads a spring on a blow-off valve in the compression circuit. Turning it in holds the rear up higher in its stroke and makes sharp hits firmer; out lets the rear sit lower and soaks up sharp hits. It changes ride height and balance as well as feel.',
  'In a fork, the base valve at the bottom of the cartridge works on the oil the rod pushes out of the cartridge, so it controls the slower, larger movements and supports the fork. The mid-valve is the compression side of the piston on the end of the rod, moving through the oil with the wheel, and it controls sharp, fast hits and how the fork holds up mid-stroke. Rebound is the other face of that same piston.',
  'A bleed shim or bleed hole is a deliberate small leak in or beside the stack, used by tuners to free up the first movement.',
  'A revalve changes the shim stacks (and sometimes pistons, bleeds and oil) to move the whole damping curve for a rider\'s weight, speed and type of riding. Ask for one when the springs and sag are right, the suspension is freshly serviced, and the clickers are at the end of their range or the complaint is at high shaft speed.',
  'Thicker oil raises damping everywhere a little and slows the clicker circuits most; it also changes more with temperature. It is not a substitute for valving. Stay with the oil on file for this bike unless a tuner specifies otherwise.',
  'Shim stacks for this bike are not on file unless verified_claims shows one. Do not write out a stack from memory or as typical. Say it is not on file, explain what a stack does, and tell the rider how a shop records one: strip the valve, lay the shims out in order, measure each diameter and thickness with a micrometer and write the list down before changing anything.']},
 {id:'worn_out',when:/\b(ran out of (clicks|adjust)|out of (clicks|adjustment)|all the way (in|out)|maxed|no more clicks|clickers? (don.?t|do not|doesn.?t) (do|change|make)|inconsistent|lap to lap|different every)\b/i,topic:'When the adjusters run out or the feel changes',points:[
  'A clicker at the end of its range is a message. In order: is the shock or fork overdue for service (old oil and low gas act like too little damping)? Are the springs right for the rider (sag pair)? Only then is it a valving question for a tuner.',
  'Feel that changes during a moto: air forks gain pressure with heat; coil forks build air in the legs (bleed them); a shock that fades needs service. Feel that changes day to day: tire pressure, sag not re-checked, temperature.']},
 {id:'transport',when:/\b(tie.?downs?|strap(s|ped)?|truck|trailer|transport|stor(e|age|ing)|winter|fork (saver|brace|support))\b/i,topic:'Transport and storage',points:[
  'Tie the bike down snug, not bottomed: enough strap to stop it moving, with the fork compressed only part way. A fork support block between the tire and fender lets you pull it tight without holding the fork deep in its travel.',
  'Holding a fork compressed for a trip does not ruin good seals or springs, but it does push air and oil pressure up in the legs: bleed the forks, wheel off the ground, when you unload.',
  'Storage: wash and dry it, wipe the fork tubes and shock shaft clean, keep it on a stand with the wheels unloaded, bleed the forks, and keep it out of the sun and damp. Check air fork pressure before the first ride back.']},
];

const SUSPENSION_TOPIC=/\b(suspension|fork|forks|shock|sag|spring|clicker|rebound|compression|damping|linkage|valving|shim|preload|nitrogen|seal|bottom(s|ing)?|harsh|headshake|wallow|pack(s|ing)?|kick(s|ing)?|pogo|stiction|air pressure|psf|aer)\b/i;
const OTHER_TOPIC=/\b(jet|jetting|carb|piston ring|top end|crank|valve clearance|gearbox|clutch|spark|ecu|map|sprocket|gearing|chain|brake pads?|tire|tyre|oil change|coolant|radiator)\b/i;

function pick(sections:Section[],text:string,max:number):PackSection[]{
 return sections.filter(s=>s.when.test(text)).slice(0,max).map(s=>({topic:s.topic,points:s.points}));
}
/** The suspension rulebook sections this question touches, or null when it is not a suspension workshop question.
 *  A short follow-up inherits the topic of the rider's last few messages. */
export function suspensionWorkshop(message:string,history:string[]=[]):SpecialistPack|null{
 const msg=message??'';let text=msg;
 if(!SUSPENSION_TOPIC.test(msg)){
  if(msg.trim().length>160||OTHER_TOPIC.test(msg))return null;
  const recent=history.slice(-3).join('\n');if(!SUSPENSION_TOPIC.test(recent))return null;text=recent+'\n'+msg;
 }
 const sections=pick(SUSPENSION,text,4);
 return sections.length?{boundary:BOUNDARY,sections}:null;
}
/* ------------------------------------------------------------------ Engine */
const ENGINE:Section[]=[
 {id:'valves',when:/\b(valves?|clearances?|shims?|tappet|bucket|feeler|tight valves?|hard (to )?start|cam timing|timing marks?|cams?|tdc)\b/i,topic:'Valve clearance and cam timing (four-stroke)',points:[
  'Check clearances with the engine fully cold. Remove the plug, turn the engine in its normal direction to top dead centre on the compression stroke (timing marks lined up, cam lobes pointing away from the buckets or rockers), and measure each valve with feeler gauges. Write every reading down before changing anything. The clearance range comes from the facts on file for this bike.',
  'New shim = old shim thickness + (measured clearance − target clearance). A tight valve (too little clearance) needs a thinner shim. Read the old shim\'s size from its marking and confirm it with a micrometer; markings wear off and shims are sometimes wrong.',
  'Tight valves are the usual direction of wear: the valve face and seat recess so the valve sits deeper in the head. Symptoms are hard starting (worst when hot), popping on decel and a hanging or uneven idle. A valve that needs a thinner shim again after only a few hours has worn through its hard coating: shimming it again only buys a short time, and the cure is new valves with the seats cut by a head shop. Dirt past the air filter is the usual killer of intake valves.',
  'Cam timing: crank locked or held at top dead centre on its mark, cams fitted with their marks where the maker shows, tensioner fitted last and released. Then turn the engine over by hand two full turns and re-check every mark before the cover goes on. If it stops hard, do not force it: a piston is touching a valve.',
  'One tooth out: hard starting, flat power, backfiring, and on a tight modern engine the valves can touch the piston and bend. Never use the starter or kickstarter to find out.',
  'A loose (noisy) valve train ticks; a cam chain rattles, loudest at a steady low rpm and often on the tensioner side. Check the tensioner\'s travel and the guides when the chain is noisy or at the hours the maker gives.']},
 {id:'top_end_4t',when:/\b(top end|piston|rings?|cylinder|bore|hone|replat|nikasil|head gasket|base gasket|compression|leak.?down|blue smoke|white smoke|oil consumption|burning oil|rebuild|big bore|break.?in)\b/i,topic:'Top end: when it is due and how it is done',points:[
  'Due when the maker\'s hours are up (use the interval on file for this bike), or sooner on these signs: harder starting, less power, oil use, smoke, or a leak-down figure that has climbed. Hours and a leak-down trend are better guides than feel.',
  'Compression test: engine warm if it will run, throttle held wide open, kick or crank until the needle stops climbing. Many four-strokes have an automatic decompressor on the cam that opens an exhaust valve at cranking speed, so the reading is low and only useful compared with the same bike when fresh. Give a target figure only if it is on file.',
  'Leak-down test: piston at top dead centre on compression, crank held so it cannot turn, regulated air into the plug hole, read the percentage lost and listen for where it goes. Hiss at the exhaust: exhaust valve. At the intake or airbox: intake valve. At the oil filler or breather: rings. Bubbles in the radiator: head gasket. It tells you which part leaks; a compression test only tells you something does.',
  'Order of a four-stroke top end: drain coolant, tank and seat off, exhaust and intake off, set top dead centre on compression, release and remove the cam chain tensioner, cams out (keep the chain from dropping), head off, cylinder off with rags under the piston, circlip and pin out. Measure before fitting: bore for wear, taper and scoring, piston skirt, ring end gap in the bore, pin and small end. Fit new rings with the gaps staggered as the maker shows, new circlips with the gap away from the cut-out, new gaskets, and torque the head in a criss-cross pattern in stages to the values on file. Then cam timing, valve clearances, coolant, and oil.',
  'Plated (Nikasil-type) cylinders are not honed like iron bores. If the plating is unworn, clean it with a scouring pad to deglaze. If it is worn through, scored or out of round it is replated or replaced. A new piston in a worn bore lasts a few hours.',
  'Never reuse head or base gaskets, and clean and check both faces for flatness with a straight edge.',
  'Smoke: blue is oil (rings and bore, or valve stem seals and guides; stem seals smoke most on start-up and after idling). White with coolant going missing is the head gasket or a cracked head; check for bubbles in the radiator and pressure test. Milky oil is coolant in the oil, usually the water pump seal or the head gasket: stop running it, because coolant ruins bearings.',
  'Break-in: warm it fully, let it cool completely, repeat a couple of heat cycles, then ride it with the load and rpm varied, no long full-throttle pulls and no lugging, for the first session. Change the oil and filter early, and re-check valve clearances, coolant and head torque where the maker calls for it.',
  'A big-bore kit raises heat and stress along with power: it needs fuelling changed to suit, shortens service intervals, and moves the bike out of its racing class.']},
 {id:'top_end_2t',when:/\b(two.?stroke|2.?stroke|2t|premix|pre-?mix|reeds?|power ?valve|ypvs|squish|crank seals?|air leak|revs? (up|to the moon)|hang(s|ing)? idle|runaway|seiz(e|ed|ure)|four.?corner|scuff|port(s|ing|ed)?|small end|arrow)\b/i,topic:'Two-stroke top end, reeds, power valve and air leaks',points:[
  'Two-stroke top end order: coolant out, pipe, head, cylinder (rag in the crankcase mouth), circlip, pin, small-end bearing. Fit the new piston with its arrow or mark toward the exhaust port so each ring end sits on its locating peg; a ring off its peg snags a port. New small-end bearing and circlips every time, ring end gap checked square in the bore with a feeler gauge against the limit on file, new gaskets, and head nuts torqued in a cross pattern in stages to the value on file.',
  'Check the bore plating at the exhaust bridge and around the ports for wear-through and scoring, and the power valve for carbon. A plated cylinder is deglazed lightly, never honed to size; worn plating means a replate.',
  'Break-in: warm up, cool fully, repeat, then short rides with the throttle blipped and varied, not held. Re-torque the head nuts when the maker says, and read the plug.',
  'Cold seizure shows as scuffing in four patches around the skirt: the piston grew faster than the cylinder because it was ridden hard before it was warm. Warm a two-stroke until the radiator is hot to the hand and ride the first lap easy.',
  'An air leak makes a two-stroke lean: the idle hangs or climbs on its own and it can rev away without throttle. Kill it with the choke or by stalling it in gear, not by waiting. Find the leak before riding: crank seals, base gasket, intake boot and reed block joints, power valve cover.',
  'Two-stroke leak-down test: block the exhaust port and the intake, pump the crankcase to a low pressure through a fitting (only a few psi; high pressure blows the seals out), and watch the gauge. It should hold with almost no drop over several minutes. Spray soapy water on the joints and both crank seals to find bubbles.',
  'Crank seals: the ignition-side seal leaks air and makes it lean and hard to idle. The clutch-side seal pulls gearbox oil into the crankcase: heavy smoke, a fouled plug, and the gearbox oil level dropping.',
  'Reeds are one-way valves between carburettor and crankcase. Replace petals that are chipped, cracked, frayed at the tips, or that no longer sit flat against the block. Bad reeds give hard starting, a poor idle and weak response off the bottom.',
  'The power valve changes the height of the exhaust port with rpm: low for bottom-end pull, open for top-end power. It sticks with carbon. Service: strip, clean the carbon off, check it moves freely through its whole travel, renew the seals, and set it to the maker\'s alignment marks.',
  'Squish is the gap between the edge of the piston crown and the head at top dead centre. Builders measure it by crushing soft solder through the plug hole and set it tight and even for a clean burn and resistance to detonation. A target figure is only given if it is on file for this engine.',
  'Porting changes when the ports open and close and how much area they have, which moves where the engine makes power: it does not add power everywhere. Raising the exhaust port adds top-end and takes bottom-end; widening adds flow but risks ring life; every cut is permanent. Explain what a builder would do and why. Never give grinding dimensions, heights or widths: they are not on file, and a wrong cut ruins the cylinder.',
  'More oil in the premix means a little less fuel in every bit of mixture, so it runs slightly leaner. Pick the maker\'s ratio on file, mix it accurately every time, and jet for that.']},
 {id:'jetting',when:/\b(jet(s|ting|ted)?|carb(uretor|uretter)?|pilot|needle|clip|main jet|air screw|fuel screw|float|overflow|bog(s|ging)?|rich|lean|plug chop|sputter|surg(e|es|ing)|elevation|altitude|humid|ethanol)\b/i,topic:'Carburettor jetting',points:[
  'Circuits by throttle position: pilot jet and air screw from closed to about a quarter; needle straight section and clip position from a quarter to three quarters; main jet from three quarters to wide open. Find where the fault is on the throttle before choosing what to change.',
  'Rich: sputters, blubbers, smokes, feels heavy and cleans up when you roll off; wet black plug. Lean: surges, pings, feels flat and hot, hangs at high rpm, bogs when the throttle is snapped open; white or grey plug. Lean at full throttle seizes two-strokes: fix it before riding hard.',
  'One change at a time, one size or one clip position, then test in the same place. Start from the stock jetting on file for this bike and the maker\'s chart for temperature and altitude when it is on file.',
  'Air screw: the best setting is where the idle is highest and response cleanest. If that ends up outside the working range (roughly under one turn or over two and a half to three out), the pilot jet is the wrong size: screw nearly closed means go bigger, screw far out means go smaller.',
  'Needle clip: lowering the clip raises the needle and richens the mid-range; raising the clip leans it.',
  'Air density: hot, humid or high-altitude air is thinner, so the bike runs richer and needs leaner jetting. Cold, dry, sea-level air is dense and needs richer jetting.',
  'Plug chop: fit a new plug, warm the bike, run it at wide open throttle under load in a tall gear for several seconds, then cut the engine and pull the clutch at the same moment and coast to a stop. Read the base ring and the bottom of the insulator.',
  'Fuel from the overflow: the float valve is not closing. Dirt on the needle or seat, a worn needle tip, a sunk or stuck float, or the wrong float height. Tap the bowl, then clean, check the height against the value on file, and replace the needle if it is ridged.',
  'Ethanol fuel absorbs water and goes stale fast, runs a little leaner, and attacks old rubber. Use fresh fuel, drain the carburettor for storage, and prefer ethanol-free when it is available.']},
 {id:'efi',when:/\b(efi|fuel.?inject(ed|ion)|injector|ecu|map(s|ping)?|fuel pump|fuel filter|fuel pressure|stall(s|ing)?|flame.?out|launch control|traction control|sensor|throttle body)\b/i,topic:'Fuel injection and maps',points:[
  'A fuel-injected bike has no jets. Fuelling is set by the ECU map and corrected by its sensors for temperature and air pressure, so altitude and weather need no change from the rider.',
  'When it runs lean, pops or stalls, check the basics first: valve clearances, air leaks at the intake boot and exhaust joint, a clean air filter, fresh fuel, the in-tank fuel filter and pump (weak pressure gives lean, flat running and hard starting), and the plug. Then the idle speed against the value on file.',
  'Stalling in corners is most often idle set too low, tight valves, a dragging clutch, or a fuel filter that is clogging.',
  'Keep fuel clean: pour through a filter funnel, keep the cap area clean, and replace the fuel filter at the interval on file or when starting gets hard.',
  'Map switch: describe what each map does only from the facts on file for this bike. In general one is the standard map and the other is softer or sharper; try both back to back on the same track.',
  'A different exhaust or airbox change alters how much air the engine moves. On most modern bikes a slip-on runs safely on the stock map; a full system or engine work wants the fuelling checked by a tuner.']},
 {id:'clutch',when:/\b(clutch|slip(s|ping)?|drag(s|ging)?|creep(s|ing)?|basket|hub|plates?|friction|free ?play)\b/i,topic:'Clutch',points:[
  'Slipping (revs rise without drive, worst in the upper gears under load): no free play at the lever, worn friction plates, tired springs, or the wrong oil. Measure plate thickness and spring free length against the limits on file and replace as a set.',
  'Dragging (creeps with the lever in, hard to find neutral): too much free play, warped steel plates, a notched basket or hub, or oil that is too thick or overfilled. Check plates for warp on a flat surface with a feeler gauge against the limit on file.',
  'Basket and hub: look at the fingers of the basket and the splines of the hub for notches worn by the plate tangs. Light notches can be dressed with a file; deep ones mean replacement, because the plates hang up in them.',
  'Fitting plates: soak new friction plates in the oil the bike uses, stack them alternately in the order the maker shows, fit the pressure plate and springs, and tighten the spring bolts a little at a time in a cross pattern to the value on file. Then set free play.',
  'Use oil made for wet clutches (JASO MA). Car oils with friction modifiers make clutches slip.']},
 {id:'bottom_end',when:/\b(bottom end|crank(shaft)?|con(necting)? ?rod|big end|main bearings?|bearings?|split(ting)? (the )?cases?|rumble|knock|vibrat|metal (in|on)|flakes?|glitter|shavings?|transmission|gearbox)\b/i,topic:'Bottom end',points:[
  'Checking the rod with the cylinder off: hold the rod and try to lift it straight up and down. Any up-and-down play at the big end means the crank needs a rebuild. Side-to-side rocking is normal; side clearance is measured with a feeler gauge against the limit on file. Check the small end and pin for blueing and scoring.',
  'Signs the bottom end is going: a deep rumble or knock that follows rpm, growing vibration, metal on the drain plug or in the filter, a crank that feels rough when turned by hand with the plug out, and main seals that keep failing.',
  'Metal in the oil: fine grey paste is normal wear. Bright aluminium flakes point to the clutch basket, piston or cases; steel slivers that stick to a magnet point to bearings, gears or the cam chain; bronze points to bushings. Chunks or a sudden increase mean stop and open it up.',
  'A full bottom-end rebuild: engine out, cases split, crank rebuilt or replaced and checked for trueness, main bearings and all seals renewed, gearbox shafts, shift forks and dogs inspected, oil pump checked on a four-stroke, new gaskets, and everything torqued to the values on file. It is the job to do together with a top end at the hours the maker gives.']},
 {id:'cooling',when:/\b(coolant|radiator|overheat(s|ing|ed)?|boil(s|ing)?|water pump|weep hole|milky|steam|hot day)\b/i,topic:'Cooling system',points:[
  'Overheating, in order: radiators blocked with mud or fins bent flat, coolant low or air-locked, a tired radiator cap that no longer holds pressure, a worn water pump impeller, slow tight riding with no airflow and a lot of clutch, lean running, and last a head gasket.',
  'Changing coolant: engine cold. Drain at the water pump drain bolt with the cap off, refill slowly with the coolant type the maker gives, open any bleed bolt and lean the bike side to side to let air out, run it briefly, let it cool and top up. Never open the cap hot.',
  'Water pump: coolant or oil from the small weep hole under the pump means a seal has failed. Milky oil is the same seal letting coolant into the gearbox or engine oil. Replace both seals and check the shaft for a worn groove where the seals ride.']},
 {id:'starting',when:/\b(won.?t start|no start|hard (to )?start|sat|sitting|stored|water|creek|drown(ed)?|hydro.?lock|kick(starter)?|flood(ed|ing)?|fuel|octane|race gas|pump gas|deton|ping|knock|warm.?up|air filter|silencer|pack(ing)?|exhaust|header|glow)\b/i,topic:'Starting, fuel and everyday engine care',points:[
  'No start after sitting: stale fuel first (drain and refill), then battery voltage on an electric-start bike, then the plug and spark, then air filter, then compression and valve clearances.',
  'Drowned engine: do not try to start it. Plug out, tip the bike back to drain the pipe, turn the engine over to pump the water out, drain the airbox and wash or replace the filter, drain the carburettor or check the fuel, change the oil (and again after a short run if it comes out milky), fit a dry plug.',
  'A kickstarter that suddenly will not go through: liquid in the cylinder (fuel or water) or a mechanical seizure. Do not force it. Pull the plug and turn it over; if it turns freely with the plug out it was hydro-locked.',
  'Fuel: use at least the octane the maker gives on file. Detonation sounds like marbles rattling under load; it comes from low octane, lean mixture, too much heat or carbon, and it breaks ring lands and pistons. Back off and fix the cause.',
  'A header that glows red while the bike idles on the stand is normal on a four-stroke: thin pipe, no airflow. Do not let it idle for long. Glowing while riding is a lean or timing problem.',
  'The air filter is the engine\'s life. Dust past it wears rings, bores and valve seats in hours. Clean and oil it every ride in dust or sand, grease the sealing rim, and check it sits square on the cage.',
  'Silencer packing burns out with hours: the bike gets louder and a two-stroke loses over-rev. Repack when it gets loud or at the maker\'s interval: drill or unbolt the end cap, pull the core, wrap new packing snugly, refit.']},
];
const ENGINE_TOPIC=/\b(engine|motor|valves?|piston|rings?|top end|bottom end|crank|cam|timing chain|tensioner|clutch|jet|jetting|carb|needle|pilot|plug|premix|reed|power ?valve|compression|leak.?down|coolant|radiator|overheat|water pump|oil|efi|inject|ecu|map|fuel|octane|deton|seiz|smoke|start|stall|idle|bog|lean|rich|exhaust|silencer|header|air filter|port(s|ing|ed)?|squish|gasket|bearing|kick(s|starter)?|hours|two.?stroke|2.?stroke|four.?stroke|4.?stroke|revs?|revving|rebuild|sputter|surg(e|es|ing)|ping|knock|flood(ed|ing)?|hydro.?lock)\b/i;

/* ------------------------------------------------------------------ Bike set-up */
const SETUP:Section[]=[
 {id:'gearing',when:/\b(gear(ing|ed)?|sprockets?|tooth|teeth|ratio|countershaft|final drive|between (second|third|2nd|3rd)|rev(s|ving)? out)\b/i,topic:'Gearing',points:[
  'Ratio = rear teeth divided by front teeth. A bigger rear or a smaller front is lower (shorter) gearing: harder pull and quicker revs in each gear, less speed per gear, more shifting. A smaller rear or bigger front is taller: longer pulls, softer hit.',
  'One tooth on the front is roughly three on the rear. Make fine changes at the rear, one tooth at a time. A smaller front sprocket also bends the chain tighter and wears it and the swingarm slider faster.',
  'Use it to put the engine in the right gear for the track: if you are stuck between two gears in most corners, go one tooth either way at the rear so one gear fits. Tight, jumpy or deep-sand tracks usually want lower gearing; fast open tracks taller. Use the sprocket sizes the maker lists for this bike when they are on file.',
  'Changing teeth moves the axle: adding teeth pulls the wheel forward (shorter wheelbase, quicker turning, less stable, more wheelie), and a big change needs a different chain length. Keep the axle near the middle of its adjustment when you can.',
  'Chain and both sprockets wear together. Fit them as a set: a new chain on hooked sprockets, or an old chain on new sprockets, wears out fast. Worn teeth look hooked or pointed like shark fins, and the chain can be lifted off the back of the rear sprocket.',
  'Steel rear sprockets last far longer; aluminium ones are lighter. Sealed (O-ring or X-ring) chains last longer and need less attention in mud and sand; non-sealed chains are lighter with slightly less drag and need constant care.']},
 {id:'chain',when:/\b(chain|slack|tension|align(ment|ed)?|master link|slider|guide)\b/i,topic:'Chain',points:[
  'Measure slack at the point and by the method the maker gives for this bike, with the value on file. If it is not on file, say so and give the method: bike on a stand, find the tightest spot by turning the wheel, and measure there.',
  'The chain is tightest when the countershaft, swingarm pivot and rear axle are in a straight line, part way through the suspension travel. A chain set tight on the stand goes bar-tight as the suspension compresses: it loads the countershaft bearing and seal and the rear hub, stops the suspension moving freely, and can snap. A little loose is safer than a little tight.',
  'Alignment: do not trust the adjuster marks alone. Measure both sides from the swingarm pivot to the axle, or sight down the chain from the rear sprocket; one-sided wear on the sprocket teeth shows misalignment.',
  'Worn out when it has stiff or kinked links, has stretched past the maker\'s limit measured over the set number of pins, or runs out of adjustment. Replace it with the sprockets.']},
 {id:'controls',when:/\b(bars?|handlebars?|levers?|perch(es)?|grips?|throttle|cable|shifter|shift lever|brake pedal|foot ?pegs?|pegs|seat|ergonom|tall|short|reach|fit|comfort|vibrat)\b/i,topic:'Controls and rider fit',points:[
  'Set the bike for the standing attack position first. Bars: start in the neutral position with the bar bend in line with the forks, then roll or move the mounts a little at a time; forward gives room and weights the front, back is easier seated but cramps standing. Tighten the clamps evenly to the values on file.',
  'Levers: angled slightly below level so the wrist is straight when standing with elbows up, moved inboard so one or two fingers reach the lever end, with the reach adjusted to hand size. Leave the perches just loose enough to rotate in a crash instead of snapping (a wrap of plastic tape under the clamp helps).',
  'Free play: set clutch and throttle free play to the values on file. Too little clutch free play makes it slip as it heats up; too much makes it drag.',
  'A throttle that does not snap shut by itself at every steering angle is a safety fault: fix it before riding. Check cable routing, kinks, free play, the throttle tube on the bar end and a dirty housing.',
  'Shift lever and brake pedal: set to boot size so the toe reaches without lifting the foot off the peg, and so the rider is not resting on the brake when standing.',
  'Tall riders: taller or more forward bars, a taller seat, and lower or set-back pegs open up the knees. Short riders: a lower seat first, then small ride-height changes (lowering link or more sag with the forks raised to match). Lowering changes geometry and uses up travel, so keep it small and balanced front to rear.',
  'Bar bend is rise, sweep and width. Cut width in small equal amounts each side and test; you cannot put it back.',
  'Grips: clean bar and throttle tube with contact cleaner, use grip glue, safety-wire them, and let them cure before riding.',
  'New vibration: engine mounts and other loose bolts first, then wheels, bearings, chain and sprockets, then bar mounts, then the engine itself.']},
 {id:'steering',when:/\b(steering|head bearings?|stem|notch(y|ed)?|damper|stabili[sz]er|headshake|pulls? to (one|the) side)\b/i,topic:'Steering',points:[
  'Steering head bearings: front wheel off the ground. Turn the bars slowly lock to lock: a notch at centre means dented races and the bearings need replacing, not adjusting. Hold the fork legs and push and pull: any knock is play. Nudge the bars from centre: they should fall to the stop smoothly without dragging.',
  'Adjust at the stem nut until play is gone and the bars still fall freely, then torque to the value on file. Clean and grease them at the maker\'s interval.',
  'A steering damper calms headshake and deflection at speed. It does not fix the cause: check sag, fork height, tire and bearings first, and set the damper only firm enough, since too much makes slow corners heavy.',
  'Bike pulls to one side: rear wheel out of line at the adjusters, forks twisted in the clamps after a crash, a bent bar, subframe or swingarm, or a wheel out of true.']},
 {id:'tires',when:/\b(tires?|tyres?|pressure|psi|knobs?|tube|mousse|bib|rim lock|bead|flat|pinch|compound|terrain|washes?|wash(ing)? out|grip|traction|hook)\b/i,topic:'Tires and pressure',points:[
  'Start from the pressure on file for this bike and move in small steps with one good gauge, tires cold. Lower pressure gives a bigger footprint and more grip on soft or slick ground but lets the tire fold, roll and pinch the tube on the rim; higher pressure protects the rim and sharpens feel on hard pack and rocks but deflects more. Half a psi can be felt.',
  'Choose the tire for the dirt you ride most: soft-terrain tires have tall, widely spaced knobs and a stiffer compound to dig and clean out; hard-terrain tires have closer, shorter knobs and a softer compound to grip a hard surface; intermediate covers the middle.',
  'A rear tire is done for racing when the leading edges of the knobs are rounded. A non-directional rear can be flipped once to use the sharp edges; replace it when both edges are gone or knobs tear.',
  'Fitting: lubricate the beads, keep the opposite bead down in the drop centre of the rim, take small bites with the irons, put a little air in the tube so it holds its shape and does not get pinched, and tighten the rim lock after the bead has seated.',
  'The rim lock clamps the bead to the rim so the tire cannot spin on the rim and tear the valve out at low pressure. Snug it to the value on file. Its weight is why some riders add a second rim lock or weights opposite it for high-speed balance; most motocross wheels are not balanced.',
  'Standard tubes are light and pinch easily; heavy-duty tubes resist pinches but add weight; a mousse cannot go flat, feels like a fixed low pressure, heats up at speed and wears out.',
  'Front washing out: check pressure and the edges of the knobs before blaming the suspension, then sag and fork height, then rider position and how the corner is entered.']},
 {id:'wheels',when:/\b(spokes?|wheel|rim|true|truing|wobble|hop|wheel bearings?|hub|axle)\b/i,topic:'Wheels',points:[
  'Spokes: tap each one with a spoke wrench; a loose spoke sounds dull. Tighten in a pattern (every third or fourth spoke, a quarter turn at a time, several times round the wheel) to the torque on file. Check them every ride on a new bike or new wheel, then regularly.',
  'Truing: wheel in the bike or a stand with a pointer at the rim. For side-to-side wobble, loosen the spokes on the side the rim leans to and tighten the opposite ones, a little at a time. For a hop, tighten the spokes at the high spot. A bent rim will not come true.',
  'Wheel bearings: wheel off the ground, hold it top and bottom and rock it; any play means bearings. Spin it and feel for roughness. Replace both bearings and the seals together and grease the seals.',
  'Tighten the axle to the value on file, and on the front let the fork settle on the axle before tightening the pinch bolts.']},
 {id:'brakes',when:/\b(brakes?|pads?|rotor|disc|bleed|spongy|fade|lever feel|pedal|caliper|fluid|dot)\b/i,topic:'Brakes',points:[
  'Spongy lever: air in the system first (bleed it), then old fluid, then pads worn or glazed, sticking caliper pins, a flexing or damaged hose, or a loose banjo bolt.',
  'Bleeding: cover the paint, fill the reservoir with fresh fluid of the type on file, fit a hose to the bleed nipple into a bottle, squeeze and hold the lever, open the nipple, close it before releasing the lever, and repeat until no bubbles come, never letting the reservoir run low. Tap the hose and caliper to free trapped bubbles.',
  'A rear brake that fades and goes long in a moto is fluid boiling: old fluid, or the rider resting a foot on the pedal so the pads drag. Change the fluid at the interval on file, set the pedal height, and check that the wheel spins free.',
  'New pads: clean the rotor with brake cleaner, then do a series of firm stops from moderate speed without locking the wheel, letting them cool between, before racing on them.',
  'Sintered pads last and work in mud and heat and are harder on rotors; organic pads have a softer feel and wear fast when wet.',
  'Rotor is finished when it is under the minimum thickness stamped on it or on file, is bent (pulsing lever), deeply grooved, blued or cracked.']},
 {id:'race_day',when:/\b(race day|pre.?race|checklist|between motos|start|gate|holeshot|launch|traction control|mud|sand|hard ?pack|slick|tacky|elevation|altitude|hot day|arenacross|supercross|outdoor|new bike|break.?in|toolbox|spares?|wash|bolt check|logbook|log book|fuel load|map)\b/i,topic:'Race day and conditions',points:[
  'Before the gate: tire pressures, chain slack and lube, spokes, axle and pinch bolts, sprocket bolts, controls and lever free play, brake pads and fluid level, oil and coolant level, clean oiled air filter, fuel, and a walk-round bolt check. Use the values on file for this bike.',
  'Between motos: air filter, chain, tire pressures, fuel, bleed the forks, look over the radiators, spokes and any bolt that has moved, and re-check anything that was changed.',
  'Bolts that come loose: spokes, sprocket bolts, axle and pinch bolts, engine mounts, subframe, triple clamps and bar mounts, footpegs, caliper and linkage bolts, plastics. Torque to the values on file, use thread-lock where the maker says, and paint-mark them so movement shows.',
  'Starts: clean the tire and the pad, pick the straightest rut, sit forward with weight over the front, steady rpm, and feed the clutch. A holeshot device latches the fork down part way so the front stays low off the line; it releases the first time the fork compresses further. Describe launch control and traction control for this bike only from the facts on file.',
  'When the track dries out and goes slick: a softer map, one gear taller and smooth throttle, a small pressure change, and slightly softer suspension. One change at a time, written down.',
  'Mud: seal the airbox and use a filter cover, spray the underside so mud sheds, protect the radiators, lower gearing if it will be heavy going, and account for the weight the mud adds (a little less sag, stiffer compression). Sand: paddle-type rear tire, lower gearing, a spare clean filter, more attention to the chain, and the rear a little lower with slower rebound.',
  'Altitude and heat: a fuel-injected bike corrects itself but makes less power in thin air, so gearing may want to go lower; a carburetted bike needs leaner jetting. In heat keep it moving, do not idle on the line, and watch coolant and tire pressures, which rise.',
  'New bike: set sag and controls, tire pressures, check spokes and every bolt, grease the linkage and steering bearings if they came dry, oil the filter, and follow the maker\'s break-in. Re-check spokes, chain and bolts after the first ride.',
  'Washing: plug the exhaust and cover the airbox, let it cool, keep the pressure washer away from bearings, seals, the chain and electrics, then dry it, run it briefly and lube the chain.',
  'Keep a log: date, track and dirt, weather, clicker and sag settings, tire and pressures, gearing, engine hours, what was changed and how it felt.',
  'Fuel is weight carried high and forward-centre: a full tank makes the bike feel heavier and sit a little lower than at the end of a moto. Set sag with the fuel level you start a race with.']},
];
const SETUP_TOPIC=/\b(gear(ing)?|sprocket|chain|bars?|handlebar|lever|grip|throttle|peg|seat|tall|short|steering|tire|tyre|pressure|spoke|wheel|rim|brake|pad|rotor|race day|checklist|moto|start|gate|holeshot|launch|traction control|mud|sand|hard ?pack|slick|elevation|arenacross|new bike|toolbox|spares?|wash|bolt|logbook|map|fit|comfort|vibrat|pulls?)\b/i;

function workshop(sections:Section[],topic:RegExp,message:string,history:string[]):SpecialistPack|null{
 const msg=message??'';let text=msg;
 if(!topic.test(msg)){
  if(msg.trim().length>160)return null;
  const recent=history.slice(-3).join('\n');if(!topic.test(recent))return null;text=recent+'\n'+msg;
 }
 const picked=pick(sections,text,3);
 return picked.length?{boundary:BOUNDARY,sections:picked}:null;
}
/** Engine rulebook sections for this question (top end, valves, jetting, injection, clutch, bottom end, cooling). */
export type EngineKind={engine?:'2-stroke'|'4-stroke';fuel?:'injected'|'carburetor'|null};
/** Sections that cannot apply to this bike are left out: no valve shims on a two-stroke, no jets on an injected bike. */
export function engineWorkshop(message:string,history:string[]=[],kind:EngineKind={}){
 const skip=new Set<string>();
 if(kind.engine==='2-stroke'){skip.add('valves');skip.add('top_end_4t');}
 if(kind.engine==='4-stroke')skip.add('top_end_2t');
 if(kind.fuel==='injected')skip.add('jetting');
 if(kind.fuel==='carburetor')skip.add('efi');
 return workshop(ENGINE.filter(s=>!skip.has(s.id)),ENGINE_TOPIC,message,history);
}
/** Bike set-up rulebook sections for this question (gearing, chain, controls, tires, wheels, brakes, race day). */
export const setupWorkshop=(message:string,history:string[]=[])=>workshop(SETUP,SETUP_TOPIC,message,history);
export const SPECIALIST_FIELDS=['suspension_workshop','engine_workshop','setup_workshop'] as const;
